import{_ as e,o as a,c as l,a2 as d}from"./chunks/framework.DQhM5RF8.js";const g=JSON.parse('{"title":"Commands List","description":"","frontmatter":{},"headers":[],"relativePath":"info/commands.md","filePath":"info/commands.md"}'),o={name:"info/commands.md"};function n(r,t,s,i,c,y){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="commands-list" tabindex="-1">Commands List <a class="header-anchor" href="#commands-list" aria-label="Permalink to &quot;Commands List&quot;">​</a></h1><p>Here are all the simple commands you can use on LlamaCraft.</p><hr><h2 id="moving-around-waypoints" tabindex="-1">Moving Around &amp; Waypoints <a class="header-anchor" href="#moving-around-waypoints" aria-label="Permalink to &quot;Moving Around &amp; Waypoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/menu</code></td><td style="text-align:left;">Opens the main server menu with quick buttons for everything.</td></tr><tr><td style="text-align:left;"><code>/spawn</code></td><td style="text-align:left;">Teleports you back to the main spawn hub.</td></tr><tr><td style="text-align:left;"><code>/tpa &lt;player&gt;</code></td><td style="text-align:left;">Asks a friend if you can teleport to them.</td></tr><tr><td style="text-align:left;"><code>/tpaccept</code></td><td style="text-align:left;">Accepts a friend&#39;s teleport request.</td></tr><tr><td style="text-align:left;"><code>/tpdeny</code></td><td style="text-align:left;">Declines a friend&#39;s teleport request.</td></tr><tr><td style="text-align:left;"><code>/sethome [name]</code></td><td style="text-align:left;">Saves your current spot as a home waypoint (e.g., <code>/sethome base</code>).</td></tr><tr><td style="text-align:left;"><code>/home [name]</code></td><td style="text-align:left;">Teleports you back to your saved home waypoint.</td></tr><tr><td style="text-align:left;"><code>/back</code></td><td style="text-align:left;">Teleports you back to where you just died or teleported from.</td></tr><tr><td style="text-align:left;"><code>/rtp</code></td><td style="text-align:left;">Teleports you to a random safe spot out in the wild.</td></tr></tbody></table><hr><h2 id="protecting-your-base" tabindex="-1">Protecting Your Base <a class="header-anchor" href="#protecting-your-base" aria-label="Permalink to &quot;Protecting Your Base&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/claim</code></td><td style="text-align:left;">Creates a protected claim around where you stand (use a Golden Shovel).</td></tr><tr><td style="text-align:left;"><code>/trust &lt;friend&gt;</code></td><td style="text-align:left;">Lets your friend build and open chests inside your base.</td></tr><tr><td style="text-align:left;"><code>/containertrust &lt;friend&gt;</code></td><td style="text-align:left;">Lets a friend open your chests, but they cannot break blocks.</td></tr><tr><td style="text-align:left;"><code>/accesstrust &lt;friend&gt;</code></td><td style="text-align:left;">Lets visitors open doors and press buttons in your base.</td></tr><tr><td style="text-align:left;"><code>/untrust &lt;friend&gt;</code></td><td style="text-align:left;">Takes away a player&#39;s permissions in your base.</td></tr><tr><td style="text-align:left;"><code>/abandonclaim</code></td><td style="text-align:left;">Deletes the claim you are standing in and gives you your blocks back.</td></tr></tbody></table><hr><h2 id="money-trading" tabindex="-1">Money &amp; Trading <a class="header-anchor" href="#money-trading" aria-label="Permalink to &quot;Money &amp; Trading&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/bal</code></td><td style="text-align:left;">Shows how many coins you have in your wallet.</td></tr><tr><td style="text-align:left;"><code>/pay &lt;player&gt; &lt;amount&gt;</code></td><td style="text-align:left;">Gives money to another player (e.g., <code>/pay Steve 500</code>).</td></tr><tr><td style="text-align:left;"><code>/shop</code></td><td style="text-align:left;">Opens the server shop to buy blocks and sell extra items.</td></tr><tr><td style="text-align:left;"><code>/ah</code></td><td style="text-align:left;">Opens the player auction house to buy and sell enchanted gear.</td></tr><tr><td style="text-align:left;"><code>/ah sell &lt;price&gt;</code></td><td style="text-align:left;">Puts the item in your hand up for sale on the auction house.</td></tr></tbody></table><hr><h2 id="talking-fun" tabindex="-1">Talking &amp; Fun <a class="header-anchor" href="#talking-fun" aria-label="Permalink to &quot;Talking &amp; Fun&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/voice</code></td><td style="text-align:left;">Gives you a private link to talk to nearby players in-game.</td></tr><tr><td style="text-align:left;"><code>/duel &lt;player&gt;</code></td><td style="text-align:left;">Challenges another player to a safe 1v1 arena duel.</td></tr><tr><td style="text-align:left;"><code>/duel accept &lt;player&gt;</code></td><td style="text-align:left;">Accepts a 1v1 arena duel challenge.</td></tr></tbody></table>',14)])])}const f=e(o,[["render",n]]);export{g as __pageData,f as default};
